# 3급 CH9 동명사 (81~90) 2차 감수
X(3, 81, r="동사의 -ing형: 대부분 -ing만 붙인다. -e로 끝나면 e를 빼고(write → writing), -ie로 끝나면 ie를 y로 바꾸고(lie → lying), ‘단모음 + 단자음’으로 끝나면 끝 자음을 한 번 더 쓴다(swim → swimming).",
  n=["단모음 + 단자음(swim)이라 m을 겹쳐 쓴 옳은 형태이므로", "단모음 + 단자음(run)이라 n을 겹쳐 쓴 옳은 형태이므로", "단모음 + 단자음(sit)이라 t를 겹쳐 쓴 옳은 형태이므로", "-e로 끝나는 write는 e를 빼고 writing으로 써야 하므로", "‘모음 + y’로 끝나는 play는 -ing만 붙이므로"],
  st="① 동사의 끝 철자를 본다: -e로 끝나는가, -ie로 끝나는가, ‘단모음 + 단자음’으로 끝나는가. → ② {0} → ③ 정답은 {a}.",
  R="write는 -e로 끝나므로 e를 빼고 writing으로 쓴다. writeing은 e를 그대로 두었다.", B="write는 -e로 끝나므로 e를 빼고 writing으로 쓴다. ④의 writing과 견주어도 ①이 틀렸다.", C="make는 -e로 끝나므로 e를 빼고 making으로 쓴다.",
  D="run은 ‘단모음 + 단자음’이라 n을 겹쳐 running으로 쓴다. runing은 n이 하나뿐이다.", E="lie는 -ie로 끝나므로 ie를 y로 바꿔 lying으로 쓴다.", F="swim은 ‘단모음 + 단자음’이라 m을 겹쳐 swimming으로 쓴다.")

X(3, 82, r="enjoy, keep, finish, avoid는 동명사를, decide, plan, hope, want, need는 to부정사를 목적어로 쓴다.",
  n=["enjoy는 동명사(watching)를 목적어로 쓰므로", "keep은 동명사(practicing)를 목적어로 쓰므로", "decide는 to부정사(to go)를 목적어로 쓰므로", "finish는 동명사(reading)를 목적어로 쓰므로", "avoid는 동명사(eating)를 목적어로 쓰므로"],
  st="① 빈칸 앞의 동사만 본다. 그 동사가 동명사를 목적어로 쓰는지 to부정사를 쓰는지가 전부다. → ② 동명사를 쓰는 동사(enjoy, keep, finish, avoid 등)의 문장을 지운다. → ③ 남는 동사는 {0}. to부정사({1})가 들어가므로 정답은 {n}.",
  R=("decide", "to go"), B=("decide", "to go"), C=("plan", "to visit"), D=("hope", "to meet"), E=("want", "to buy"), F=("need", "to finish"))

X(3, 83, r="-ing형이 주어·목적어·보어로 쓰이면 동명사(~하는 것), be동사와 함께 진행형을 만들면 현재분사(~하고 있는)다.",
  n=["주어로 쓰인 동명사이므로", "be동사(are)와 함께 진행형을 만드는 현재분사이므로", "주어로 쓰인 동명사이므로", "like의 목적어로 쓰인 동명사이므로", "주어로 쓰인 동명사이므로"],
  st="① 밑줄 친 -ing형 바로 앞을 본다. be동사가 있으면 진행형(현재분사)일 수 있다. → ② ‘~하는 것’으로 풀리면 동명사, ‘~하고 있다’로 풀리면 현재분사다. → ③ {0} 정답은 {n}.",
  R="②만 are discussing(논의하고 있다)으로 진행형이다. 나머지는 주어나 목적어 자리의 동명사다.", B="③만 are discussing으로 진행형이다. 나머지는 주어나 목적어 자리의 동명사다.", C="②만 is reading(읽고 있다)으로 진행형이다.",
  D="③만 was running(달리고 있었다)으로 진행형이다.", E="④만 are studying(공부하고 있다)으로 진행형이다.", F="③만 was cooking(요리하고 있었다)으로 진행형이다.")

X(3, 84, r="look forward to의 to는 전치사라 뒤에 동명사를 쓴다. can't help -ing, be busy -ing, finish -ing도 동명사를 쓰고, expect는 to부정사를 쓴다.",
  n=["can't help + -ing(~하지 않을 수 없다)로 옳으므로", "look forward to 뒤에는 동명사(meeting)를 써야 하므로", "be busy + -ing(~하느라 바쁘다)로 옳으므로", "expect + to부정사로 옳으므로", "finish + 동명사로 옳으므로"],
  st="① 문장마다 -ing형이나 to부정사 앞의 표현을 찾는다(전치사, 관용 표현, 동사). → ② 전치사와 look forward to, feel like 뒤에는 동명사가 와야 한다. → ③ {0} 정답은 {n}.",
  R="②는 look forward to 뒤에 동사원형 meet을 썼다. meeting으로 고친다.", B="②는 look forward to 뒤에 동사원형 meet을 썼다. ④처럼 meeting이어야 한다.", C="④는 전치사 in 뒤에 동사원형 learn을 썼다. learning으로 고친다.",
  D="④는 전치사 at 뒤에 동사원형 play를 썼다. playing으로 고친다.", E="③은 feel like 뒤에 to부정사를 썼다. feel like drinking으로 고친다.", F="③은 전치사 about 뒤에 동사원형 move를 썼다. moving으로 고친다.")

X(3, 85, r="avoid, give up, enjoy, finish, keep은 동명사를, plan, decide, want, hope는 to부정사를 목적어로 쓴다.",
  pre=["문장별 판정: ⓐ O. plan + to부정사. ⓑ X. avoid는 동명사(avoided meeting). ⓒ O. decide + to부정사. ⓓ X. give up은 동명사(gave up solving)."],
  n=["ⓐ가 옳은 문장이므로", "ⓐ, ⓒ 모두 옳은 문장이므로", "ⓒ가 옳은 문장이므로", "ⓑ와 ⓓ가 모두 어색하므로", "ⓒ가 옳은 문장이므로"],
  st="① 밑줄 친 부분의 앞 동사가 동명사를 쓰는 동사인지 to부정사를 쓰는 동사인지 가른다. → ② {0} → ③ 정답은 {a}.",
  R="plan, decide는 to부정사를 쓰므로 ⓐ, ⓒ는 옳다. avoid, give up은 동명사를 쓰므로 ⓑ(avoided to meet), ⓓ(gave up to solve)가 어색하다.", B="avoid, enjoy는 동명사를 쓰므로 b(avoided to meet), d(enjoys to read)가 어색하다. a, c, e는 옳다.",
  C="keep은 동명사를 쓰므로 b(keeps to talk)가 어색하다. 나머지는 옳다.", D="finish는 동명사를 쓰므로 c(finished to work)가 어색하다. 나머지는 옳다.", E="want는 to부정사를 쓰므로 b(wants learning)가 어색하다. 나머지는 옳다.",
  F="plan은 to부정사를 쓰므로 b(plans visiting)가 어색하다. 나머지는 옳다.")

X(3, 86, r="전치사 뒤에 동사를 쓸 때는 동명사(-ing)로 쓴다. mind도 동명사를 목적어로 쓰고, look forward to의 to는 전치사다.",
  n=["전치사 about 뒤에 동사원형을 쓸 수 없으므로", "전치사 뒤에 to부정사를 쓸 수 없으므로", "전치사 about 뒤에는 동명사를 쓰므로", "전치사 뒤에 과거형을 쓸 수 없으므로", "전치사 뒤에 3인칭 단수 현재형을 쓸 수 없으므로"],
  st="① 빈칸 바로 앞의 말({0})을 본다. → ② {1} 뒤에 동사를 쓰려면 동명사(-ing)로 써야 한다. → ③ 정답은 {a}.",
  R=("feel about", "전치사 about"), B=("feel about", "전치사 about"), C=("interested in", "전치사 in"), D=("What about", "전치사 about"), E=("mind", "동명사를 목적어로 쓰는 동사 mind"), F=("look forward to", "전치사 to"))
RV(3, 86, "C", v="수정(내용)", why="정답 확인. 다만 오답에 영어에 없는 말(learnings)이 있어 형태만으로 지워진다. 원문항의 오답은 모두 실제 동사 형태(join, to join, joined, joins)다. 원문항은 두 사람의 대화인데 한 사람의 말 한 줄뿐인 점도 다르다.", fix="learnings를 learned로, 대답 한 줄을 더함")
RV(3, 86, "DEF", v="수정(표기)", why="정답 확인. 다만 원문항은 두 사람이 주고받는 대화인데 변형은 한 사람의 말 한 줄뿐이라 발문(‘다음 대화에서’)과 맞지 않는다. 오답 goings·openings·meetings도 동사의 형태가 아니다.", fix="대답 한 줄을 더하고 오답을 동사 형태로")

